# Offline artwork generation only. No texture or sprite is generated by the game.
Add-Type -AssemblyName System.Drawing
$assetDir = Join-Path $PSScriptRoot '../Assets/Resources/GameplaySprites'
foreach ($illuminated in @($false, $true)) {
    $bitmap = [System.Drawing.Bitmap]::new(256, 320)
    $graphics = [System.Drawing.Graphics]::FromImage($bitmap)
    $graphics.Clear([System.Drawing.Color]::Transparent)
    $graphics.SmoothingMode = [System.Drawing.Drawing2D.SmoothingMode]::AntiAlias
    $graphics.TranslateTransform(128, 160)
    $graphics.ScaleTransform(8, 8)
    $corners = [System.Drawing.PointF[]]@(
        [System.Drawing.PointF]::new(0,-16), [System.Drawing.PointF]::new(12,0),
        [System.Drawing.PointF]::new(0,16), [System.Drawing.PointF]::new(-12,0))
    $shades = @(191,82,115,242)
    for ($i = 0; $i -lt 4; $i++) {
        $brush = [System.Drawing.SolidBrush]::new([System.Drawing.Color]::FromArgb(255,$shades[$i],$shades[$i],$shades[$i]))
        $graphics.FillPolygon($brush, [System.Drawing.PointF[]]@([System.Drawing.PointF]::new(0,0),$corners[$i],$corners[($i+1)%4]))
        $brush.Dispose()
    }
    $outer = [System.Drawing.PointF[]]@($corners | ForEach-Object { [System.Drawing.PointF]::new($_.X*1.2,$_.Y*1.2) })
    if ($illuminated) {
        foreach ($stroke in @(@(4.5,31),@(2.8,61))) {
            $pen = [System.Drawing.Pen]::new([System.Drawing.Color]::FromArgb($stroke[1],255,255,255),[single]$stroke[0])
            $graphics.DrawPolygon($pen,$outer)
            $pen.Dispose()
        }
    }
    $pen = [System.Drawing.Pen]::new([System.Drawing.Color]::White,1.1)
    $graphics.DrawPolygon($pen,$outer)
    $pen.Dispose()
    $pen = [System.Drawing.Pen]::new([System.Drawing.Color]::White,.65)
    $graphics.DrawPolygon($pen,$corners)
    $pen.Dispose()
    $pen = [System.Drawing.Pen]::new([System.Drawing.Color]::FromArgb(128,255,255,255),.55)
    foreach ($corner in $corners) { $graphics.DrawLine($pen,[System.Drawing.PointF]::new(0,0),$corner) }
    $pen.Dispose()
    $graphics.Dispose()
    $name = if ($illuminated) { 'UpgradeDiamondLit' } else { 'UpgradeDiamond' }
    $bitmap.Save((Join-Path $assetDir ($name+'.png')),[System.Drawing.Imaging.ImageFormat]::Png)
    $bitmap.Dispose()
}
